@page "/recipes/{CategoryName}"
@using RecipeCommunity.Services
@using RecipeCommunity.Models
@inject RecipeService RecipeService

<PageTitle>@CategoryName Recipes - Recipe Community</PageTitle>

<div class="container">
    <nav class="breadcrumb">
        <a href="/">Home</a> &rsaquo; <span>@CategoryName</span>
    </nav>

    <h1>@CategoryName Recipes</h1>

    @if (Recipes.Any())
    {
        <div class="recipe-list">
            @foreach (var recipe in Recipes)
            {
                <a href="/recipe/@recipe.Id" class="recipe-card">
                    <h3>@recipe.Title</h3>
                    <div class="recipe-meta">
                        <span class="rating">⭐ @recipe.AverageRating.ToString("F1")</span>
                        <span class="rating-count">(@recipe.RatingCount ratings)</span>
                    </div>
                </a>
            }
        </div>
    }
    else
    {
        <p class="empty-state">No recipes found in this category yet. <a href="/submit">Be the first to submit one!</a></p>
    }
</div>

@code {
    [Parameter]
    public string CategoryName { get; set; } = string.Empty;

    private List<Recipe> Recipes { get; set; } = new();

    protected override void OnParametersSet()
    {
        CategoryName = System.Globalization.CultureInfo.CurrentCulture.TextInfo.ToTitleCase(CategoryName);
        Recipes = RecipeService.GetRecipesByCategory(CategoryName);
    }
}

@page "/recipe/{Id:int}"
@using RecipeCommunity.Services
@using RecipeCommunity.Models
@inject RecipeService RecipeService

<PageTitle>@(Recipe?.Title ?? "Recipe") - Recipe Community</PageTitle>

<div class="container">
    @if (Recipe is not null)
    {
        <nav class="breadcrumb">
            <a href="/">Home</a> &rsaquo; <a href="/recipes/@Recipe.Category.ToLower()">@Recipe.Category</a> &rsaquo; <span>@Recipe.Title</span>
        </nav>

        <article class="recipe-detail">
            <h1>@Recipe.Title</h1>
            <div class="recipe-meta">
                <span class="category-badge">@Recipe.Category</span>
                <span class="rating">⭐ @Recipe.AverageRating.ToString("F1") (@Recipe.RatingCount ratings)</span>
            </div>

            <section class="recipe-section">
                <h2>🧾 Ingredients</h2>
                <ul class="ingredients-list">
                    @foreach (var ingredient in Recipe.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries))
                    {
                        <li>@ingredient</li>
                    }
                </ul>
            </section>

            <section class="recipe-section">
                <h2>📝 Instructions</h2>
                <div class="steps-list">
                    @foreach (var step in Recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
                    {
                        <p>@step</p>
                    }
                </div>
            </section>

            <section class="recipe-section rating-section">
                <h2>⭐ Rate this Recipe</h2>
                <StarRating RecipeId="Recipe.Id" @rendermode="InteractiveServer" />
            </section>
        </article>
    }
    else
    {
        <p class="empty-state">Recipe not found.</p>
    }
</div>

@code {
    [Parameter]
    public int Id { get; set; }

    private Recipe? Recipe { get; set; }

    protected override void OnParametersSet()
    {
        Recipe = RecipeService.GetRecipeById(Id);
    }
}

@using RecipeCommunity.Services
@inject RecipeService RecipeService

<div class="star-rating-widget">
    <div class="stars">
        @for (int i = 1; i <= 5; i++)
        {
            var starValue = i;
            <button class="star-btn @(starValue <= (HoverRating > 0 ? HoverRating : SelectedRating) ? "active" : "")"
                    @onclick="() => Rate(starValue)"
                    @onmouseover="() => HoverRating = starValue"
                    @onmouseout="() => HoverRating = 0"
                    disabled="@Submitted">
                ★
            </button>
        }
    </div>
    @if (Submitted)
    {
        <p class="rating-feedback">Thank you! You rated this recipe @SelectedRating star@(SelectedRating != 1 ? "s" : "").</p>
    }
    else
    {
        <p class="rating-prompt">Click a star to rate</p>
    }
</div>

@code {
    [Parameter]
    public int RecipeId { get; set; }

    private int SelectedRating { get; set; }
    private int HoverRating { get; set; }
    private bool Submitted { get; set; }

    private void Rate(int rating)
    {
        if (!Submitted)
        {
            SelectedRating = rating;
            Submitted = true;
            RecipeService.RateRecipe(RecipeId, rating);
        }
    }
}

@page "/submit"
@using RecipeCommunity.Models
@using RecipeCommunity.Services
@rendermode InteractiveServer
@inject RecipeService RecipeService

<PageTitle>Submit a Recipe - Recipe Community</PageTitle>

<div class="container">
    <nav class="breadcrumb">
        <a href="/">Home</a> &rsaquo; <span>Submit Recipe</span>
    </nav>

    <h1>📝 Submit a Recipe</h1>
    <p>Share your favorite recipe with the community!</p>

    @if (IsSubmitted)
    {
        <div class="success-message">
            <h2>🎉 Recipe Submitted!</h2>
            <p>Thank you for sharing "<strong>@Submission.Title</strong>" with the community.</p>
            <a href="/" class="btn-primary">Back to Home</a>
        </div>
    }
    else
    {
        <EditForm Model="Submission" OnValidSubmit="HandleSubmit" class="recipe-form">
            <DataAnnotationsValidator />
            <ValidationSummary />

            <div class="form-group">
                <label for="title">Recipe Title</label>
                <InputText id="title" @bind-Value="Submission.Title" placeholder="e.g., Grandma's Apple Pie" />
                <ValidationMessage For="() => Submission.Title" />
            </div>

            <div class="form-group">
                <label for="category">Category</label>
                <InputSelect id="category" @bind-Value="Submission.Category">
                    <option value="">-- Select a category --</option>
                    @foreach (var cat in RecipeService.GetCategories())
                    {
                        <option value="@cat.Name">@cat.Name</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => Submission.Category" />
            </div>

            <div class="form-group">
                <label for="ingredients">Ingredients</label>
                <InputTextArea id="ingredients" @bind-Value="Submission.Ingredients" rows="6" placeholder="One ingredient per line&#10;e.g.,&#10;2 cups flour&#10;1 cup sugar&#10;3 eggs" />
                <ValidationMessage For="() => Submission.Ingredients" />
            </div>

            <div class="form-group">
                <label for="steps">Preparation Steps</label>
                <InputTextArea id="steps" @bind-Value="Submission.Steps" rows="8" placeholder="Describe each step clearly&#10;e.g.,&#10;1. Preheat oven to 350°F.&#10;2. Mix dry ingredients..." />
                <ValidationMessage For="() => Submission.Steps" />
            </div>

            <button type="submit" class="btn-primary">Submit Recipe</button>
        </EditForm>
    }
</div>

@code {
    private RecipeSubmission Submission { get; set; } = new();
    private bool IsSubmitted { get; set; }

    private void HandleSubmit()
    {
        RecipeService.AddRecipe(Submission);
        IsSubmitted = true;
    }
}

